import ImageIO
import SwiftUI

// MARK: - Surface textures

/// Photographic door surfaces, generated by `Design/doors/textures.py` and bundled with
/// the app and the widget: brushed metals lit by a window, glossy enamel reflecting a room.
enum DoorTexture {
    private static let cache = NSCache<NSString, UIImage>()

    /// The surface for a finish, decoded no larger than `maxPixel` (the widget has little memory).
    static func image(for finish: DoorFinish, maxPixel: CGFloat) -> UIImage? {
        let bucket = Int((min(max(maxPixel, 64), 1200) / 128).rounded(.up)) * 128
        let key = "\(finish.rawValue)-\(bucket)" as NSString
        if let cached = cache.object(forKey: key) { return cached }
        guard let url = Bundle.main.url(forResource: "door-\(finish.rawValue)", withExtension: "jpg"),
              let image = FridgeStorage.downsampledImage(at: url, maxPixel: CGFloat(bucket)) else { return nil }
        cache.setObject(image, forKey: key)
        return image
    }
}

extension DoorFinish {
    /// Average colour of the surface: used before the texture loads and for small swatches.
    var baseColor: Color {
        switch self {
        case .steel: return Color(hex: 0xC6C9CC)
        case .graphite: return Color(hex: 0x575B60)
        case .champagne: return Color(hex: 0xCEC2B2)
        case .cream: return Color(hex: 0xECE0C5)
        case .mint: return Color(hex: 0xBAE1CC)
        case .sky: return Color(hex: 0xA6CBE8)
        case .cherry: return Color(hex: 0xCE342E)
        case .lemon: return Color(hex: 0xF1D462)
        case .powder: return Color(hex: 0xF0C4CC)
        case .black: return Color(hex: 0x222428)
        }
    }

    var isDark: Bool { self == .graphite || self == .black || self == .cherry }
}

/// The door surface filling its frame: the photographic texture plus a faint sheen that
/// drifts as the phone tilts. No rim, no frame: the door is one clean surface.
struct DoorSurfaceView: View {
    let finish: DoorFinish

    @Environment(\.displayScale) private var displayScale

    var body: some View {
        GeometryReader { geo in
            let maxPixel = max(geo.size.width, geo.size.height) * displayScale
            ZStack {
                finish.baseColor
                if let texture = DoorTexture.image(for: finish, maxPixel: maxPixel) {
                    Image(uiImage: texture)
                        .resizable()
                        .scaledToFill()
                        .frame(width: geo.size.width, height: geo.size.height)
                        .clipped()
                }
                DoorSheen(isMetal: finish.isMetal)
            }
        }
    }
}

/// A barely visible glint that slides across the surface with tilt. Still in the widget.
private struct DoorSheen: View {
    let isMetal: Bool

    @Environment(\.magnetLight) private var light

    var body: some View {
        let shift = light.tilt.dx * 0.18 + light.tilt.dy * 0.06
        if isMetal {
            LinearGradient(stops: [
                Gradient.Stop(color: Color.white.opacity(0), location: 0),
                Gradient.Stop(color: Color.white.opacity(0), location: max(0, 0.42 + shift)),
                Gradient.Stop(color: Color.white.opacity(abs(light.tilt.dx) * 0.12), location: min(1, 0.5 + shift)),
                Gradient.Stop(color: Color.white.opacity(0), location: min(1, 0.58 + shift)),
                Gradient.Stop(color: Color.white.opacity(0), location: 1),
            ], startPoint: .leading, endPoint: .trailing)
            .allowsHitTesting(false)
        } else {
            LinearGradient(stops: [
                Gradient.Stop(color: Color.white.opacity(0), location: 0),
                Gradient.Stop(color: Color.white.opacity(0), location: max(0, 0.35 + shift)),
                Gradient.Stop(color: Color.white.opacity(0.06 + abs(light.tilt.dx) * 0.08), location: min(1, 0.45 + shift)),
                Gradient.Stop(color: Color.white.opacity(0), location: min(1, 0.55 + shift)),
                Gradient.Stop(color: Color.white.opacity(0), location: 1),
            ], startPoint: .topLeading, endPoint: .bottomTrailing)
            .allowsHitTesting(false)
        }
    }
}

/// Shared proportions of a door.
enum DoorGeometry {
    /// Outer corner radius in the app. The widget uses the system shape, which this matches.
    static func cornerRadius(format: FridgeFormat, size: CGSize) -> CGFloat {
        switch format {
        case .tall: return size.width * 0.062
        case .square: return size.width * 0.13
        case .wide: return size.height * 0.13
        }
    }
}

// MARK: - Door

/// The door: its surface and the optional chrome nameplate. Fills the proposed rectangle;
/// the caller (or the widget container) clips the corners.
struct DoorBackgroundView: View {
    let design: DoorDesign
    let format: FridgeFormat

    var body: some View {
        GeometryReader { geo in
            let size = geo.size
            ZStack {
                DoorSurfaceView(finish: design.finish)
                if !design.nameplate.isEmpty {
                    let height = format == .wide ? size.height * 0.12 : size.height * 0.075
                    NameplateView(text: design.nameplate, finish: design.finish)
                        .frame(width: size.width * 0.6, height: height)
                        .position(x: size.width * 0.07 + size.width * 0.3,
                                  y: size.height * (format == .wide ? 0.13 : 0.075))
                }
            }
        }
    }
}

/// A plain piece of a finish, e.g. as the backdrop of a preview.
struct DoorPanelView: View {
    let finish: DoorFinish
    let cornerRadius: CGFloat

    var body: some View {
        DoorSurfaceView(finish: finish)
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
    }
}

/// A retro chrome script plate.
private struct NameplateView: View {
    let text: String
    let finish: DoorFinish

    var body: some View {
        GeometryReader { geo in
            let size = geo.size.height * 0.95
            let font = Font.custom("MarckScript-Regular", fixedSize: size)
            ZStack(alignment: .leading) {
                Text(text)
                    .font(font)
                    .foregroundStyle(Color.black.opacity(finish.isDark ? 0.55 : 0.3))
                    .offset(x: size * 0.03, y: size * 0.06)
                    .blur(radius: size * 0.02)
                Text(text)
                    .font(font)
                    .foregroundStyle(LinearGradient(colors: [Color.white, Color(hex: 0xB9BEC4), Color(hex: 0x6E747B), Color(hex: 0xE6E9EC)],
                                                    startPoint: .top, endPoint: .bottom))
                Text(text)
                    .font(font)
                    .foregroundStyle(Color.white.opacity(0.7))
                    .mask {
                        LinearGradient(colors: [Color.white, Color.clear], startPoint: .top, endPoint: .center)
                    }
                    .offset(y: -size * 0.02)
            }
            .lineLimit(1)
            .minimumScaleFactor(0.5)
            .frame(width: geo.size.width, height: geo.size.height, alignment: .leading)
        }
        .allowsHitTesting(false)
    }
}
